const summary = JSON.parse(Buffer.from($input.first().binary.data.data, 'base64').toString());
const aiData  = JSON.parse(Buffer.from($input.last().binary.data.data,  'base64').toString());

const winner = summary.winner_excitement_index;
const kpis   = summary.kpis || {};
const moviesText = Object.entries(aiData.summaries || {}).map(([movie, text]) =>
  `**${movie}**\n${text.slice(0, 500)}...`
).join('\n\n---\n\n');

return [{
  json: {
    subject: `📊 Cultural Sentiment Daily Digest — ${new Date().toLocaleDateString('en-US', {weekday:'long', month:'long', day:'numeric'})}`,
    winner,
    total_posts: summary.total_posts,
    alerts: summary.alerts_triggered,
    movies_text: moviesText,
    generated_at: summary.generated_at,
  }
}];

